# Hypothesis: Fill 0s that are on a straight line between two 2s (horizontally or vertically)
def transform_v2(grid):
    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]
    filled = set()

    # Check horizontal segments
    for r in range(h):
        # Find all 2s in this row
        cols_with_2 = [c for c in range(w) if grid[r][c] == 2]
        if len(cols_with_2) >= 2:
            for i in range(len(cols_with_2)):
                for j in range(i + 2, len(cols_with_2)):
                    # All cells between cols_with_2[i] and cols_with_2[j] should be 0
                    all_zeros = all(grid[r][k] == 0 for k in range(cols_with_2[i] + 1, cols_with_2[j]))
                    if all_zeros:
                        for k in range(cols_with_2[i] + 1, cols_with_2[j]):
                            filled.add((r, k))

    # Check vertical segments
    for c in range(w):
        rows_with_2 = [r for r in range(h) if grid[r][c] == 2]
        if len(rows_with_2) >= 2:
            for i in range(len(rows_with_2)):
                for j in range(i + 2, len(rows_with_2)):
                    all_zeros = all(grid[k][c] == 0 for k in range(rows_with_2[i] + 1, rows_with_2[j]))
                    if all_zeros:
                        for k in range(rows_with_2[i] + 1, rows_with_2[j]):
                            filled.add((k, c))

    # Fill with 1
    for r, c in sorted(filled):
        result[r][c] = 1

    return result

