def transform_ev2(grid):
    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    # Horizontal: fill 0s where left_dist == right_dist
    for r in range(h):
        cols = sorted([c for c in range(w) if grid[r][c] == 2])
        for i in range(len(cols) - 1):
            left, right = cols[i], cols[i+1]
            for c in range(left + 1, right):
                if grid[r][c] == 0:
                    if (c - left) == (right - c):
                        result[r][c] = 1

    # Vertical: fill 0s where top_dist == bottom_dist
    for c in range(w):
        rows = sorted([r for r in range(h) if grid[r][c] == 2])
        for i in range(len(rows) - 1):
            top, bottom = rows[i], rows[i+1]
            for r in range(top + 1, bottom):
                if grid[r][c] == 0:
                    if (r - top) == (bottom - r):
                        result[r][c] = 1

    return result

